<div class="tabs"><?php foreach(['basic'=>'Thông tin cơ bản','experiences'=>'Kinh nghiệm','educations'=>'Học vấn','skills'=>'Kỹ năng','projects'=>'Dự án','certifications'=>'Chứng chỉ'] as $section=>$label): ?><a href="#editor-<?= e($section) ?>"><?= e($label) ?></a><?php endforeach; ?></div>
<section class="panel" id="editor-basic"><h2>Thông tin cơ bản</h2><form data-api="/users/me/profile" data-method="PATCH" data-reload><?php foreach(['fullName'=>'Họ và tên','headline'=>'Chức danh chuyên môn','location'=>'Địa điểm'] as $field=>$fieldLabel): ?><label><?= e($fieldLabel) ?><input name="<?= e($field) ?>" value="<?= e($data[$field]??'') ?>" <?= $field==='fullName'?'required':'' ?>></label><?php endforeach; ?><label>Giới thiệu bản thân<textarea name="about"><?= e($data['about']??'') ?></textarea></label><button>Lưu thông tin</button></form><div class="grid two section"><?php foreach(['avatar'=>'Ảnh đại diện','cover'=>'Ảnh bìa'] as $kind=>$kindLabel): ?><form data-upload="/users/me/<?= e($kind) ?>" data-reload><label><?= e($kindLabel) ?><input type="file" name="file" accept="image/png,image/jpeg,image/webp" required></label><button class="ghost">Cập nhật</button></form><?php endforeach; ?></div></section>
<?php foreach(['experiences'=>'Kinh nghiệm','educations'=>'Học vấn','projects'=>'Dự án','certifications'=>'Chứng chỉ'] as $key=>$sectionLabel): ?><section class="panel section" id="editor-<?= e($key) ?>"><h2><?= e($sectionLabel) ?></h2><?php foreach($data[$key]??[] as $item): ?><article class="profile-child-card"><h3><?= e($item['position']??$item['school']??$item['title']??$item['name']??'') ?></h3><p><?= e($item['company']??$item['degree']??$item['issuer']??'') ?></p><details><summary>Chỉnh sửa</summary><?php $editItem=$item;require APP_ROOT.'/views/partials/profile-item-form.php';unset($editItem); ?></details><button class="ghost" data-action="/users/me/<?= e($key) ?>/<?= e($item['id']) ?>" data-method="DELETE" data-reload>Xóa</button></article><?php endforeach; ?><details class="section"><summary>+ Thêm <?= e(mb_strtolower($sectionLabel)) ?></summary><?php require APP_ROOT.'/views/partials/profile-item-form.php'; ?></details></section><?php endforeach; ?>
<section class="panel section" id="editor-skills"><h2>Kỹ năng</h2><div class="chips"><?php foreach($data['skills']??[] as $skill): ?><span><?= e($skill['skill']['name']) ?> · <?= e($skill['level']) ?><button class="icon-button" aria-label="Xóa kỹ năng" data-action="/users/me/skills/<?= e($skill['skillId']) ?>" data-method="DELETE" data-reload><?= ui_icon('close',12) ?></button></span><?php endforeach; ?></div><form data-api="/users/me/skills" data-reload><label>Tên kỹ năng<input name="name" required></label><label>Trình độ<select name="level"><?php foreach(['BEGINNER','INTERMEDIATE','ADVANCED','EXPERT'] as $level): ?><option <?= $level==='INTERMEDIATE'?'selected':'' ?>><?= e($level) ?></option><?php endforeach; ?></select></label><label>Số năm kinh nghiệm<input name="yearsExp" type="number" min="0" step="0.1"></label><button>Thêm kỹ năng</button></form></section>
<section class="panel section" id="editor-languages"><h2>Ngôn ngữ và liên kết</h2><form data-profile-links data-api="/users/me/profile" data-method="PATCH" data-reload><label>Ngôn ngữ (dấu phẩy)<input name="languages" value="<?= e(implode(', ',array_column($data['languages']??[],'name'))) ?>"></label><?php foreach(['github','linkedin','website','portfolio','twitter'] as $link): ?><label><?= e(ucfirst($link)) ?><input type="url" name="<?= e($link) ?>" value="<?= e($data['socialLinks'][$link]??'') ?>"></label><?php endforeach; ?><button>Lưu liên kết</button></form></section>
